/*
Name: frmOATarjetaVISA
Author: Global
Description: Objeto afectado del reclamo para el ramo 52 (Riesgos Varios, tarjeta VISA).
             - Seccion Info con un unico campo obligatorio: Descripcion (texto libre, hasta 2000 caracteres).
             - Sin comandos ni triggers: toda la logica vive en el formulario y no hace llamadas.
Category: FORM
Version: 1.00
CreateDate: 30-09-2026
*/

var me = this;

(function () {
  var CSS = [
    '.oa-seccion{color:#15428b;font-weight:600;border-bottom:1px solid #99bbe8;padding-bottom:3px;margin:6px 0 4px}',
    '.oa-tv-descripcion{min-height:110px;resize:vertical}'
  ].join('');

  function rootForm() {
    var $root = $('.rendered-form').first();
    if (!$root.length) $root = $('[name="colDescripcion"]').closest('form');
    return $root;
  }

  function addStyle($root) {
    if ($root.find('style.oa-tv-style').length) return;
    $('<style class="oa-tv-style"></style>').text(CSS).prependTo($root);
  }

  function fire(element, type) {
    if (typeof Event === 'function') element.dispatchEvent(new Event(type, { bubbles: true }));
    else $(element).trigger(type);
  }

  // Quita espacios sobrantes al salir del campo y avisa a la pantalla para que guarde el valor limpio.
  function limpiar(element) {
    var actual = element.value == null ? '' : String(element.value);
    var limpio = actual.trim();
    if (limpio === actual) return;
    element.value = limpio;
    fire(element, 'input');
    fire(element, 'change');
  }

  function initialize() {
    var $root = rootForm();
    if (!$root.length) return;
    addStyle($root);
    $root.find('[name="colDescripcion"]').addClass('oa-tv-descripcion');

    $root.off('.oaTarjetaVISA')
      .on('blur.oaTarjetaVISA', '[name="colDescripcion"]', function () { limpiar(this); });
  }

  initialize();
})();
